using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Media.Imaging;using System.Windows.Threading;using System.Web.Script.Serialization;using D=System.Drawing;
class SettingsLayoutTests {
 static int checks,failures;static void Check(bool v,string n){checks++;Console.WriteLine((v?"PASS ":"FAIL ")+n);if(!v)failures++;}static object Get(object o,string n){return o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).GetValue(o);}static object Call(object o,string n,params object[] a){return o.GetType().GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).Invoke(o,a);}static IEnumerable<DependencyObject> Tree(DependencyObject o){yield return o;for(int i=0;i<VisualTreeHelper.GetChildrenCount(o);i++)foreach(var v in Tree(VisualTreeHelper.GetChild(o,i)))yield return v;}static T Named<T>(DependencyObject w,string n)where T:DependencyObject{Pump();return Tree(w).OfType<T>().First(c=>System.Windows.Automation.AutomationProperties.GetName(c)==n);}static void Pump(){var frame=new DispatcherFrame();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(100)};timer.Tick+=(s,e)=>{timer.Stop();frame.Continue=false;};timer.Start();Dispatcher.PushFrame(frame);}static void Click(Window w,string n){Tree(w).OfType<Button>().First(b=>Convert.ToString(b.Content)==n).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();}static void Shot(Window w,string path){w.UpdateLayout();var root=(FrameworkElement)w.Content;var b=new RenderTargetBitmap((int)root.ActualWidth,(int)root.ActualHeight,96,96,PixelFormats.Pbgra32);b.Render(root);var e=new PngBitmapEncoder();e.Frames.Add(BitmapFrame.Create(b));using(var f=File.Create(path))e.Save(f);}
 static int Different(D.Bitmap a,D.Bitmap b){int count=0;for(int y=0;y<a.Height;y++)for(int x=0;x<a.Width;x++)if(a.GetPixel(x,y)!=b.GetPixel(x,y))count++;return count;}

 [STAThread]static int Main(string[] args){Directory.CreateDirectory(args[0]);Window pet=null;var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};try{
 var ramp=UsageRamp.Preset("侦探蓝");string color=ramp.Stops[1].Color;Check(ramp.MoveStop(1,62.5)&&ramp.Stops[1].Position==62.5&&ramp.Stops[1].Color==color&&ramp.Stops.Count==4,"drag preserves point identity color and count");Check(!ramp.MoveStop(0,20)&&!ramp.MoveStop(3,90),"gradient endpoints stay anchored");ramp.MoveStop(1,99);Check(ramp.Stops[1].Position<80,"drag cannot cross adjacent point");Check(!ramp.MoveStop(1,Double.NaN)&&!ramp.MoveStop(-1,5),"invalid drag input ignored");ramp.Validate();
 foreach(double dpi in new[]{1d,1.25,1.5,2})foreach(string mode in new[]{"square","rounded","feather","fragments"}){
 var a=new TaskbarAppearance{AutoTheme=false,Graphs=true,GraphFrame=true,BarValueOnly=true,BarEdge=mode,ProtectText=false};a.EnsureItems();var cfg=new MonitorConfig{Appearance=a,TaskbarItems=new List<string>{"cpu","memory"}};var sample=new SystemSample{Cpu=75,MemoryUsed=16,MemoryTotal=32};var layout=TaskbarPainter.Geometry(cfg,dpi,200,sample);
 using(var graph=new D.Bitmap(layout.Size.Width,layout.Size.Height))using(var plain=new D.Bitmap(layout.Size.Width,layout.Size.Height)){
 using(var g=D.Graphics.FromImage(graph)){g.Clear(D.Color.FromArgb(20,30,40));TaskbarPainter.Draw(g,cfg,sample,dpi,layout);}a.Graphs=false;using(var g=D.Graphics.FromImage(plain)){g.Clear(D.Color.FromArgb(20,30,40));TaskbarPainter.Draw(g,cfg,sample,dpi,layout);}bool identical=true;foreach(var rect in layout.Labels)for(int y=(int)Math.Ceiling(rect.Y);y<(int)rect.Bottom;y++)for(int x=(int)Math.Ceiling(rect.X);x<(int)rect.Right;x++)if(graph.GetPixel(x,y)!=plain.GetPixel(x,y))identical=false;Check(identical,"value-only bar leaves label pixels intact "+mode+" DPI "+dpi);Check(Different(graph,plain)>0,"value region still shows actual occupancy "+mode+" DPI "+dpi);if(dpi==1&&mode=="fragments"){graph.Save(Path.Combine(args[0],"value-only-bars.png"));}
 }}
 var json=new JavaScriptSerializer();var stored=new TaskbarAppearance{BarValueOnly=true};var reloaded=json.Deserialize<TaskbarAppearance>(json.Serialize(stored));reloaded.Validate();Check(reloaded.BarValueOnly,"value-only selection survives serialization");
 pet=(Window)Activator.CreateInstance(typeof(ConanPet),true);var assistant=(AssistantRuntime)Get(pet,"assistant");assistant.Config.Monitor.Quota.Enabled=false;assistant.Config.Monitor.Appearance.AutoTheme=false;((VoiceRuntime)Get(pet,"voices")).Settings.Enabled=false;pet.Show();Pump();((System.Threading.Timer)Get(pet,"assistantTimer")).Change(-1,-1);((DispatcherTimer)Get(pet,"ticker")).Stop();((DispatcherTimer)Get(pet,"skillTicker")).Stop();Call(pet,"OpenTerminal");var w=(TerminalWindow)Get(pet,"terminal");w.Width=1220;w.Height=980;w.ShowPage("任务栏外观");Click(w,"布局与屏幕");var scroll=(ScrollViewer)Get(w,"pageScroll");var preview=(FrameworkElement)Get(w,"taskbarPreview");var apply=Tree(w).OfType<Button>().First(b=>Convert.ToString(b.Content)=="应用并保存任务栏外观");
 foreach(int height in new[]{740,980}){w.Height=height;Pump();scroll.ScrollToTop();Pump();double py=preview.TranslatePoint(new Point(0,0),w).Y,fy=apply.TranslatePoint(new Point(0,0),w).Y;scroll.ScrollToEnd();Pump();Check(scroll.VerticalOffset>0&&Math.Abs(py-preview.TranslatePoint(new Point(0,0),w).Y)<.1,"preview frozen while settings scroll at height "+height);Check(Math.Abs(fy-apply.TranslatePoint(new Point(0,0),w).Y)<.1&&fy+apply.ActualHeight<w.ActualHeight,"apply controls fixed and visible at height "+height);}
 w.Height=980;scroll.ScrollToTop();Pump();Shot(w,Path.Combine(args[0],"fixed-layout-top.png"));scroll.ScrollToEnd();Pump();Shot(w,Path.Combine(args[0],"fixed-layout-bottom.png"));foreach(string heading in new[]{"排列与宽度","屏幕与窗口位置","逐列数值宽度","宽高自适应","项目间距","四边留白"})Check(Tree(w).OfType<TextBlock>().Any(t=>t.Text==heading),"explicit layout section "+heading);
 Click(w,"配色与文字");scroll.ScrollToEnd();Pump();Named<ComboBox>(w,"配色预设").SelectedItem="NVIDIA 绿";var bar=Named<UsageRampBar>(w,"可编辑配色条");Pump();int hit=bar.PointAt(6+(bar.ActualWidth-12)*.5,43);Check(hit==1&&bar.Cursor!=System.Windows.Input.Cursors.Cross,"color markers have precise hit areas and no plus cursor");bar.MovePoint(hit,65);Pump();Check(bar.Ramp.Stops.Count==4&&bar.Ramp.Stops[hit].Position==65&&Named<TextBox>(w,"配色颜色点位置").Text=="65","marker movement synchronizes position field and preview without adding points");bar.Selected=hit;bar.RaiseEvent(new System.Windows.Input.KeyEventArgs(System.Windows.Input.Keyboard.PrimaryDevice,PresentationSource.FromVisual(bar),0,System.Windows.Input.Key.Left){RoutedEvent=System.Windows.Input.Keyboard.KeyDownEvent});Pump();Check(bar.Ramp.Stops[hit].Position==64,"keyboard can fine-tune selected draggable point");Shot(w,Path.Combine(args[0],"draggable-color-points.png"));
 Click(w,"占用条效果");Named<ComboBox>(w,"占用条填充位置").SelectedIndex=1;Click(w,"应用并保存任务栏外观");Check(assistant.Config.Monitor.Appearance.BarValueOnly,"value-only control applied to live configuration");var runtime=new AssistantRuntime(AppDomain.CurrentDomain.BaseDirectory);Check(runtime.Config.Monitor.Appearance.BarValueOnly&&runtime.Config.Monitor.Appearance.LabelRamp.Stops.Any(s=>s.Position==64),"dragged point and fill placement survive runtime restart");runtime.Telemetry.Dispose();Shot(w,Path.Combine(args[0],"bar-placement-settings.png"));w.SetTheme("b",false);Pump();Shot(w,Path.Combine(args[0],"fixed-layout-theme-b.png"));
 w.ShowPage("启动与窗口");Pump();Check(((FrameworkElement)Get(w,"pinnedSettingsTop")).Visibility==Visibility.Collapsed&&((FrameworkElement)Get(w,"pinnedSettingsBottom")).Visibility==Visibility.Collapsed,"navigation releases sticky taskbar controls on other pages");Check(Tree(w).OfType<TextBlock>().Any(t=>t.Text=="Windows 登录启动"),"startup settings show semantic subheading");w.ShowPage("气泡外观");Pump();Check(Tree(w).OfType<TextBlock>().Any(t=>t.Text=="文字与阅读尺寸"),"bubble settings grouped by purpose");w.ShowPage("动作与移动");Pump();Check(Tree(w).OfType<TextBlock>().Any(t=>t.Text=="足球互动"),"companion settings separate football from movement");w.ShowPage("任务栏外观");Pump();Check(((FrameworkElement)Get(w,"pinnedSettingsBottom")).Visibility==Visibility.Visible,"returning to taskbar rebuilds sticky controls without parent conflicts");
 }catch(Exception e){Console.WriteLine("FAIL "+e);failures++;}finally{if(pet!=null)pet.Close();app.Shutdown();}File.WriteAllText(Path.Combine(args[0],"settings-layout-results.json"),new JavaScriptSerializer().Serialize(new{checks,failures,isolated_settings=true,hardware_mouse_drag_tested=false,drag_model_hit_testing_and_keyboard_tested=true}));return failures==0?0:1;}
}
